query:
query sidebar {
  viewer {
    id
    ... on Member {
      leagues(current: true) {
        id
        slug
        name
        isDefault
        isElectronicPaymentsEnabled
        __typename
      }
      __typename
    }
    ... on ExternalStaff {
      leagues {
        id
        slug
        name
        __typename
      }
      __typename
    }
    __typename
  }
}
